(6528543, 971141, 96751, '<td valign="top">Star and orb.  Nicely done.</td>', 'Star and orb.  Nicely done.', '2011-09-05 04:12:29.000000', NULL, 1),
(6528544, 970814, 96751, '<td valign="top">John, this should be doing exceptionally well.  A standout in the challenge.</td>', 'John, this should be doing exceptionally well.  A standout in the challenge.', '2011-09-05 04:12:58.000000', NULL, 1),
