(6528546, 970952, 96751, '<td valign="top">Very majestic</td>', 'Very majestic', '2011-09-05 04:13:23.000000', NULL, 1),
(6528547, 971255, 96751, '<td valign="top">This has got to be Finland or Iceland or something with absurdly gorgeous scenery.  Beautiful capture.</td>', 'This has got to be Finland or Iceland or something with absurdly gorgeous scenery.  Beautiful capture.', '2011-09-05 04:13:56.000000', NULL, 1),
(6528548, 970849, 96751, '<td valign="top">They''re like little orange canoes on the lake.</td>', 'They''re like little orange canoes on the lake.', '2011-09-05 04:14:11.000000', NULL, 1),
(6528549, 971223, 96751, '<td valign="top">What a fantastic pov!!!!  I love this image.  So much to absorb, enjoy.  Gorgeous flare, and the textured sky.  The exceptionally detailed pigeon, the drops from the fountain.  And the tower piercing the sky.  Great balance.  A fave.</td>', 'What a fantastic pov!!!!  I love this image.  So much to absorb, enjoy.  Gorgeous flare, and the textured sky.  The exceptionally detailed pigeon, the drops from the fountain.  And the tower piercing the sky.  Great balance.  A fave.', '2011-09-05 04:15:04.000000', NULL, 1),
(6528550, 970841, 96751, '<td valign="top">That''s what I call framing!</td>', 'That''s what I call framing!', '2011-09-05 04:15:34.000000', NULL, 1),
(6528551, 971213, 96751, '<td valign="top">There is something very simple and tender about this image.</td>', 'There is something very simple and tender about this image.', '2011-09-05 04:15:57.000000', NULL, 1),
(6528552, 971310, 96751, '<td valign="top">Great colors!</td>', 'Great colors!', '2011-09-05 04:16:16.000000', NULL, 1),
(6528553, 971217, 96751, '<td valign="top">I love the pp''ing on the rear flowers. They look so delicate.  The front flower looks a bit thick and heavy.  But the flares are heavenly.</td>', 'I love the pp''ing on the rear flowers. They look so delicate.  The front flower looks a bit thick and heavy.  But the flares are heavenly.', '2011-09-05 04:16:50.000000', NULL, 1),
(6528554, 971051, 96751, '<td valign="top">Nice!</td>', 'Nice!', '2011-09-05 04:16:58.000000', NULL, 1),
(6528555, 971316, 96751, '<td valign="top">Last of the summer sunsets.</td>', 'Last of the summer sunsets.', '2011-09-05 04:17:31.000000', NULL, 1),
(6528556, 970726, 96751, '<td valign="top">This is so strange!</td>', 'This is so strange!', '2011-09-05 04:17:48.000000', NULL, 1),
(6528559, 970862, 96751, '<td valign="top">Odd but interesting pp''ing.</td>', 'Odd but interesting pp''ing.', '2011-09-05 04:18:04.000000', NULL, 1),
(6528560, 970989, 96751, '<td valign="top">Beautiful.  I love the little flare in the lower right corner.</td>', 'Beautiful.  I love the little flare in the lower right corner.', '2011-09-05 04:18:28.000000', NULL, 1),
(6528561, 971361, 96751, '<td valign="top">As if swans needed to be any more beautiful.  I think this is what the sounds they hear look like.</td>', 'As if swans needed to be any more beautiful.  I think this is what the sounds they hear look like.', '2011-09-05 04:19:02.000000', NULL, 1),
(6528562, 970963, 96751, '<td valign="top">LOVE this.  What a clean, richly toned image.</td>', 'LOVE this.  What a clean, richly toned image.', '2011-09-05 04:19:31.000000', NULL, 1),
(6528563, 971207, 96751, '<td valign="top">As if the grandeur of the evening was pushing them to the side.</td>', 'As if the grandeur of the evening was pushing them to the side.', '2011-09-05 04:20:05.000000', NULL, 1),
(6528566, 971132, 96751, '<td valign="top">I suspect this will place at the top.  Flares like Christmas lights.</td>', 'I suspect this will place at the top.  Flares like Christmas lights.', '2011-09-05 04:20:30.000000', NULL, 1),
(6528568, 971208, 96751, '<td valign="top">Historic flare.</td>', 'Historic flare.', '2011-09-05 04:20:55.000000', NULL, 1),
(6528569, 970581, 96751, '<td valign="top">I love this image, Deb.  Your flare is like Tinkerbell.  You have to believe in it to see it :-)  I''m kidding.  The flare is there for everyone to see.</td>', 'I love this image, Deb.  Your flare is like Tinkerbell.  You have to believe in it to see it :-)  I''m kidding.  The flare is there for everyone to see.', '2011-09-05 04:21:37.000000', NULL, 1),
(6528570, 971232, 96751, '<td valign="top">Magical.</td>', 'Magical.', '2011-09-05 04:21:57.000000', NULL, 1),
(6528572, 969956, 101668, '<td valign="top">Well thought out and fantastically done. Beautiful picture telling a story and flair flare!</td>', 'Well thought out and fantastically done. Beautiful picture telling a story and flair flare!', '2011-09-05 04:24:21.000000', NULL, 1),
(6528573, 971121, 96751, '<td valign="top">Such a powerful image, Ben.  Reminiscent of Icarus.</td>', 'Such a powerful image, Ben.  Reminiscent of Icarus.', '2011-09-05 04:25:07.000000', NULL, 1),
(6528574, 971095, 96751, '<td valign="top">Gorgeous child.</td>', 'Gorgeous child.', '2011-09-05 04:25:20.000000', NULL, 1),
(6528577, 971213, 108580, '<td valign="top">Nice positioning of the flare in the heart of the flower</td>', 'Nice positioning of the flare in the heart of the flower', '2011-09-05 04:45:10.000000', NULL, 1),
(6528579, 971051, 108580, '<td valign="top">Yay a Star Burst <u>flare</u>! Nice positioning in the hand. Is that a statue? Also a teeny aperture flare for a belly button.</td>', 'Yay a Star Burst flare! Nice positioning in the hand. Is that a statue? Also a teeny aperture flare for a belly button.', '2011-09-05 04:46:23.000000', NULL, 1),
(6528591, 970952, 86218, '<td valign="top">How can you go wrong with a shot like this. 8</td>', 'How can you go wrong with a shot like this. 8', '2011-09-05 05:14:26.000000', NULL, 1),
(6528617, 971257, 22459, '<td valign="top">nice flare! not sure if the tilted glass works?</td>', 'nice flare! not sure if the tilted glass works?', '2011-09-05 07:19:09.000000', NULL, 1),
(6528623, 971205, 108069, '<td valign="top">Hey, I''ve stayed right by there! Nice scene. Early morning feel. Good balance between the top of the bridge and the sun. Nice drops of flare.</td>', 'Hey, I''ve stayed right by there! Nice scene. Early morning feel. Good balance between the top of the bridge and the sun. Nice drops of flare.', '2011-09-05 07:26:45.000000', NULL, 1),
(6528626, 971284, 108069, '<td valign="top">Awesome shot. Flare really adds to the scene. Lovely mood. Well done.</td>', 'Awesome shot. Flare really adds to the scene. Lovely mood. Well done.', '2011-09-05 07:27:56.000000', NULL, 1),
(6528629, 970842, 108069, '<td valign="top">Lovely shot. Flare really makes the image, not just making an appearance. Excellent stuff.</td>', 'Lovely shot. Flare really makes the image, not just making an appearance. Excellent stuff.', '2011-09-05 07:29:23.000000', NULL, 1),
(6528638, 971299, 108580, '<td valign="top">Technically adept. The studio light as ball hovering over her hand and attracting the butterflies. Star burst and aperture flare. Front page material.</td>', 'Technically adept. The studio light as ball hovering over her hand and attracting the butterflies. Star burst and aperture flare. Front page material.', '2011-09-05 07:38:12.000000', NULL, 1),
(6528639, 970862, 108069, '<td valign="top">Very, very nice. Beautiful scene, and the flare really adds a lovely element. Perfect composition with the flare and of course the rest of it. Well done.</td>', 'Very, very nice. Beautiful scene, and the flare really adds a lovely element. Perfect composition with the flare and of course the rest of it. Well done.', '2011-09-05 07:41:03.000000', NULL, 1),
(6528640, 971283, 108069, '<td valign="top">Nice contrast and balance. The sun''s flare is a nice reminiscent inverse to the bird''s wings. Cool photo.</td>', 'Nice contrast and balance. The sun''s flare is a nice reminiscent inverse to the bird''s wings. Cool photo.', '2011-09-05 07:43:05.000000', NULL, 1),
(6528644, 970979, 108580, '<td valign="top">Super use of the star burst flare to add feeling and interest to the image.</td>', 'Super use of the star burst flare to add feeling and interest to the image.', '2011-09-05 08:01:12.000000', NULL, 1),
(6528646, 970986, 73942, '<td valign="top">This came out really good, I love the sun burst, and like all the detail you brought out in the trees, also good title choice!</td>', 'This came out really good, I love the sun burst, and like all the detail you brought out in the trees, also good title choice!', '2011-09-05 08:02:15.000000', NULL, 1),
(6528647, 970850, 108580, '<td valign="top">Simple, elegant, subtle.</td>', 'Simple, elegant, subtle.', '2011-09-05 08:03:10.000000', NULL, 1),
(6528651, 971282, 108580, '<td valign="top">Lovely. For all other challenges you would be hammered for the blown highlighted sun lol. Yet here it works. I like the blown hair flare effect. Pity about hte fence line behind...</td>', 'Lovely. For all other challenges you would be hammered for the blown highlighted sun lol. Yet here it works. I like the blown hair flare effect. Pity about hte fence line behind...', '2011-09-05 08:04:29.000000', NULL, 1),
(6528653, 971279, 108580, '<td valign="top">Simple abstract pattern with flare. It''s there but so minimal. Needless to say the point of all lens coatings and internal design, ELD, SD glass is to counteract flaws and imperfections as much as possible. I have no problem with an entry that is not in your face flare, but I fear voters expect it to be the primary FP.</td>', 'Simple abstract pattern with flare. It''s there but so minimal. Needless to say the point of all lens coatings and internal design, ELD, SD glass is to counteract flaws and imperfections as much as possible. I have no problem with an entry that is not in your face flare, but I fear voters expect it to be the primary FP.', '2011-09-05 08:11:53.000000', NULL, 1),
(6528654, 971334, 108580, '<td valign="top">I was wondering when a ''flash'' (or globe?-can''t see the power cable) flare would come into play in this challenge. You''ve captured both star burst flare and aperture flare.</td>', 'I was wondering when a ''flash'' (or globe?-can''t see the power cable) flare would come into play in this challenge. You''ve captured both star burst flare and aperture flare.', '2011-09-05 08:27:41.000000', NULL, 1),
(6528655, 971322, 108580, '<td valign="top">Bjorn Borg? LOL. Nice flash or studio light star burst and aperture flare in one.</td>', 'Bjorn Borg? LOL. Nice flash or studio light star burst and aperture flare in one.', '2011-09-05 08:29:24.000000', NULL, 1),
(6528656, 970661, 108580, '<td valign="top">Unique and DMC. PP painting/oil effect works.</td>', 'Unique and DMC. PP painting/oil effect works.', '2011-09-05 08:30:10.000000', NULL, 1),
(6528658, 969883, 135937, '<td valign="top">I googled "lens flare" when this challenge first came out, and there was an image just like this on the first page of results, but not quite as well done. I like this. =) *6*</td>', 'I googled "lens flare" when this challenge first came out, and there was an image just like this on the first page of results, but not quite as well done. I like this. =) *6*', '2011-09-05 08:31:09.000000', NULL, 1),
(6528666, 970968, 135937, '<td valign="top">Wow, this lens flare is scary great. =) Excellent control of light! I didn''t care as much for your background, but the flare is definitely substantial.  *6* for being able to capture such an incredible flare! =)</td>', 'Wow, this lens flare is scary great. =) Excellent control of light! I didn''t care as much for your background, but the flare is definitely substantial.  *6* for being able to capture such an incredible flare! =)', '2011-09-05 08:34:10.000000', NULL, 1),
(6528667, 971299, 114233, '<td valign="top">Where have I seen those butterflies before? I hope this entry doesn''t get a DQ for a reflector disappearing this time! Lighting is awesome as usual and the lens flare is subtle and gentle just like butterflies!</td>', 'Where have I seen those butterflies before? I hope this entry doesn''t get a DQ for a reflector disappearing this time! Lighting is awesome as usual and the lens flare is subtle and gentle just like butterflies!', '2011-09-05 08:34:37.000000', NULL, 1),
(6528668, 970842, 135937, '<td valign="top">I love the dark, moody composition in this! Absolutely beautiful. *7*</td>', 'I love the dark, moody composition in this! Absolutely beautiful. *7*', '2011-09-05 08:34:47.000000', NULL, 1),
(6528669, 971217, 135937, '<td valign="top">Oh I love the colors in this! And your flare works so well with the overall composition! *8*</td>', 'Oh I love the colors in this! And your flare works so well with the overall composition! *8*', '2011-09-05 08:35:22.000000', NULL, 1),
(6528671, 971180, 135937, '<td valign="top">I really like the composition of this photograph, however it feels a little washed out and overexposed to me. The flare turned out pretty epic though and that''s such a pretty web!</td>', 'I really like the composition of this photograph, however it feels a little washed out and overexposed to me. The flare turned out pretty epic though and that''s such a pretty web!', '2011-09-05 08:36:47.000000', NULL, 1),
(6528672, 970852, 135937, '<td valign="top">Great use of balance and symmetry! I am very much enjoying this photograph.</td>', 'Great use of balance and symmetry! I am very much enjoying this photograph.', '2011-09-05 08:38:04.000000', NULL, 1),
(6528673, 971141, 135937, '<td valign="top">How clever! This is a great shot!</td>', 'How clever! This is a great shot!', '2011-09-05 08:38:31.000000', NULL, 1),
(6528674, 970849, 135937, '<td valign="top">James Taylor. Appropriate title. =) Beautiful sunset.</td>', 'James Taylor. Appropriate title. =) Beautiful sunset.', '2011-09-05 08:39:16.000000', NULL, 1),
(6528675, 971322, 135937, '<td valign="top">Haha, fun! He looks a little crazy, like he just blew something up in his evil-archnemesis lab. *7*</td>', 'Haha, fun! He looks a little crazy, like he just blew something up in his evil-archnemesis lab. *7*', '2011-09-05 08:40:25.000000', NULL, 1),
(6528676, 970952, 135937, '<td valign="top">Breathtaking view. *8*</td>', 'Breathtaking view. *8*', '2011-09-05 08:41:26.000000', NULL, 1),
(6528677, 970091, 108580, '<td valign="top">Unique POV and subtle star burst flare</td>', 'Unique POV and subtle star burst flare', '2011-09-05 08:41:32.000000', NULL, 1),
(6528679, 971310, 135937, '<td valign="top">Great POV! I love this. *8*</td>', 'Great POV! I love this. *8*', '2011-09-05 08:41:56.000000', NULL, 1),
(6528681, 971332, 135937, '<td valign="top">I love the perspective and framing of this photo, however it feels somewhat flat to me. =/ *5*</td>', 'I love the perspective and framing of this photo, however it feels somewhat flat to me. =/ *5*', '2011-09-05 08:43:01.000000', NULL, 1),
(6528682, 971255, 108580, '<td valign="top">Nice use of flare on your UWA. Leads eye into the image.</td>', 'Nice use of flare on your UWA. Leads eye into the image.', '2011-09-05 08:43:19.000000', NULL, 1),
(6528683, 970977, 135937, '<td valign="top">Oh, Happy!!!!!!!!  The colors in this are delightful! *7*</td>', 'Oh, Happy!!!!!!!!  The colors in this are delightful! *7*', '2011-09-05 08:43:33.000000', NULL, 1),
(6528684, 971118, 108580, '<td valign="top">1st flare only image. Bold and DMC.</td>', '1st flare only image. Bold and DMC.', '2011-09-05 08:44:08.000000', NULL, 1),
(6528685, 971232, 108580, '<td valign="top">Tops use of flare to accentuate image and lead the eye</td>', 'Tops use of flare to accentuate image and lead the eye', '2011-09-05 08:44:35.000000', NULL, 1),
(6528686, 971261, 108580, '<td valign="top">Holy cow, does that lens have no special coated glass? Highly unusual flare.</td>', 'Holy cow, does that lens have no special coated glass? Highly unusual flare.', '2011-09-05 08:46:01.000000', NULL, 1),
(6528687, 971355, 135937, '<td valign="top">How morbid! I really love the juxtaposition of such a dark subject and so much light. It works! *8*</td>', 'How morbid! I really love the juxtaposition of such a dark subject and so much light. It works! *8*', '2011-09-05 08:46:02.000000', NULL, 1),
(6528688, 970792, 108580, '<td valign="top">Snap. Only more accentuated than mine. Love the backlit grass. Are those Protea bushes?</td>', 'Snap. Only more accentuated than mine. Love the backlit grass. Are those Protea bushes?', '2011-09-05 08:47:03.000000', NULL, 1),
(6528689, 971332, 108580, '<td valign="top">Great use of flare and silhouette. Should do well.</td>', 'Great use of flare and silhouette. Should do well.', '2011-09-05 08:47:46.000000', NULL, 1),
(6528690, 971299, 135937, '<td valign="top">This is so magical! The butterflies are a great touch. *8*</td>', 'This is so magical! The butterflies are a great touch. *8*', '2011-09-05 08:48:16.000000', NULL, 1),
(6528693, 970269, 108580, '<td valign="top">It works and adds to the image. DMC.</td>', 'It works and adds to the image. DMC.', '2011-09-05 08:50:39.000000', NULL, 1),
(6528694, 971223, 108580, '<td valign="top">Super work. Has an out of balance...balance!</td>', 'Super work. Has an out of balance...balance!', '2011-09-05 08:52:01.000000', NULL, 1),
(6528695, 970365, 19825, '<td valign="top">Beautiful landscape, Kristina.</td>', 'Beautiful landscape, Kristina.', '2011-09-05 08:53:09.000000', NULL, 1),
(6528696, 970985, 135937, '<td valign="top">Eerie</td>', 'Eerie', '2011-09-05 08:54:18.000000', NULL, 1),
(6528698, 971243, 108580, '<td valign="top">DMC. Star burst flare is flare. There are 2 other tiny visible aperture flares as well. This should do well as do most seascapes of this quality on DPC. Will give the "star burst is not flare" crowd a dilemma. Front page I hope.</td>', 'DMC. Star burst flare is flare. There are 2 other tiny visible aperture flares as well. This should do well as do most seascapes of this quality on DPC. Will give the "star burst is not flare" crowd a dilemma. Front page I hope.', '2011-09-05 08:55:00.000000', NULL, 1),
(6528699, 971261, 132177, '<td valign="top"><u></u></td>', '', '2011-09-05 08:55:51.000000', NULL, 1),
(6528700, 971284, 135937, '<td valign="top">I especially love her dress (I have a thing for dresses). This photograph is lovely.  *7*</td>', 'I especially love her dress (I have a thing for dresses). This photograph is lovely.  *7*', '2011-09-05 08:57:09.000000', NULL, 1),
(6528701, 970862, 135937, '<td valign="top">Such an appropriate title! So beautiful! The colors are superb and so very soothing. *8*</td>', 'Such an appropriate title! So beautiful! The colors are superb and so very soothing. *8*', '2011-09-05 08:58:25.000000', NULL, 1),
(6528703, 970861, 135937, '<td valign="top">Creepy.</td>', 'Creepy.', '2011-09-05 08:58:48.000000', NULL, 1),
(6528704, 970852, 108580, '<td valign="top">Only the third flash/strobe/globe image so far. Superbly clear and well conceptualised. Front page?</td>', 'Only the third flash/strobe/globe image so far. Superbly clear and well conceptualised. Front page?', '2011-09-05 08:59:14.000000', NULL, 1),
(6528705, 971331, 108580, '<td valign="top">Subtle flare used effectively on either side to accentuate subject. Nice urban-mod subject.</td>', 'Subtle flare used effectively on either side to accentuate subject. Nice urban-mod subject.', '2011-09-05 09:00:33.000000', NULL, 1),
(6528706, 971132, 135937, '<td valign="top">I like how regal this photograph feels. And great color! *8*</td>', 'I like how regal this photograph feels. And great color! *8*', '2011-09-05 09:00:43.000000', NULL, 1),
(6528707, 970814, 108069, '<td valign="top">Heck of a photo, buddy. Unbelievable amount of flare, and it truly enhances the scene. Great composition, and as always, top processing. Excellent stuff.</td>', 'Heck of a photo, buddy. Unbelievable amount of flare, and it truly enhances the scene. Great composition, and as always, top processing. Excellent stuff.', '2011-09-05 09:02:50.000000', NULL, 1),
(6528709, 971265, 108580, '<td valign="top">Hardly any visible aperture flare (I see one circle) let alone star burst flare. Perhaps a few on the beak ridge. I also saw this challenge as not only having to be dozens of flares but a creative minimalist way of using lens flare to achieve a unique and appealing image as this. The sun itself has been flared by the optics. Good optics reduce and minimise flare. Kit lenses need good control to try and minimise them. I''ll be keen to see what lens this is and in who''s capable hands.</td>', 'Hardly any visible aperture flare (I see one circle) let alone star burst flare. Perhaps a few on the beak ridge. I also saw this challenge as not only having to be dozens of flares but a creative minimalist way of using lens flare to achieve a unique and appealing image as this. The sun itself has been flared by the optics. Good optics reduce and minimise flare. Kit lenses need good control to try and minimise them. I''ll be keen to see what lens this is and in who''s capable hands.', '2011-09-05 09:05:34.000000', NULL, 1),
(6528713, 971205, 108580, '<td valign="top">Lovely work.</td>', 'Lovely work.', '2011-09-05 09:09:00.000000', NULL, 1),
(6528721, 971077, 108580, '<td valign="top">Beautiful backlighting and subtle star burst flare. Sharp, with basic neutral colours. Nice!</td>', 'Beautiful backlighting and subtle star burst flare. Sharp, with basic neutral colours. Nice!', '2011-09-05 09:22:01.000000', NULL, 1),
(6528729, 970064, 108580, '<td valign="top">Dreamy image, with a tad of flare. Simple.</td>', 'Dreamy image, with a tad of flare. Simple.', '2011-09-05 09:31:29.000000', NULL, 1),
(6528731, 971234, 108580, '<td valign="top">Star burst flare and no aperture flare, not that I can pick up. Very much DMC. Also a creative shot using the reflection and burst to improve the composition and highlight the spectators on the pier. WD.</td>', 'Star burst flare and no aperture flare, not that I can pick up. Very much DMC. Also a creative shot using the reflection and burst to improve the composition and highlight the spectators on the pier. WD.', '2011-09-05 09:34:54.000000', NULL, 1),
(6528733, 970645, 108580, '<td valign="top">Love the emotion and innocence. The flare, both star and aperture put to good use. I don''t like the building behind.</td>', 'Love the emotion and innocence. The flare, both star and aperture put to good use. I don''t like the building behind.', '2011-09-05 09:36:01.000000', NULL, 1),
(6528735, 970215, 132251, '<td valign="top">I wish the DOF was greater and the flare was more prominent.</td>', 'I wish the DOF was greater and the flare was more prominent.', '2011-09-05 09:45:41.000000', NULL, 1),
(6528740, 971257, 132251, '<td valign="top">Very cool, but the name doesn''t really fit... Nightcap in sunlight?</td>', 'Very cool, but the name doesn''t really fit... Nightcap in sunlight?', '2011-09-05 10:02:23.000000', NULL, 1),
(6528743, 969878, 132251, '<td valign="top">Are those specks birds or dust? I like the contrasting names.</td>', 'Are those specks birds or dust? I like the contrasting names.', '2011-09-05 10:05:12.000000', NULL, 1),
(6528744, 970726, 132251, '<td valign="top">Strange, like an inverted layer was overlayed.</td>', 'Strange, like an inverted layer was overlayed.', '2011-09-05 10:06:04.000000', NULL, 1),
(6528746, 970968, 132251, '<td valign="top">Whoa, most predominant flare so far.</td>', 'Whoa, most predominant flare so far.', '2011-09-05 10:07:00.000000', NULL, 1);
