INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6532833, 970989, 33672, '<td valign="top">Nice and simple. Great work.</td>', 'Nice and simple. Great work.', '2011-09-08 01:50:13.000000', NULL, 1),
(6533650, 970968, 16106, '<td valign="top">My pick for blue, the orange flare works well against the trees</td>', 'My pick for blue, the orange flare works well against the trees', '2011-09-08 19:32:01.000000', NULL, 1),
(6533652, 971132, 16106, '<td valign="top">Nice use of converging lines to accent the flare and use it as a compositional element to add to the image.</td>', 'Nice use of converging lines to accent the flare and use it as a compositional element to add to the image.', '2011-09-08 19:33:11.000000', NULL, 1),
(6533653, 971118, 16106, '<td valign="top">Lovely minimalist approach.</td>', 'Lovely minimalist approach.', '2011-09-08 19:33:52.000000', NULL, 1),
(6533655, 971143, 16106, '<td valign="top">Nice juxtaposition of geometric forms. Ought to contend.</td>', 'Nice juxtaposition of geometric forms. Ought to contend.', '2011-09-08 19:35:20.000000', NULL, 1),
(6533656, 970952, 16106, '<td valign="top">A lovely shot, I just wish the flare was a stronger element, good enough for HM, but just a bit more would have put it at the top.</td>', 'A lovely shot, I just wish the flare was a stronger element, good enough for HM, but just a bit more would have put it at the top.', '2011-09-08 19:37:07.000000', NULL, 1),
(6534258, 970814, 83313, '<td valign="top">A recognizable locale, PP style and self portrait. Nicely done, as usual. You have those fascinating European streets and you do know how to milk them.</td>', 'A recognizable locale, PP style and self portrait. Nicely done, as usual. You have those fascinating European streets and you do know how to milk them.', '2011-09-09 00:59:27.000000', NULL, 1),
(6534481, 971335, 64446, '<td valign="top">I like the composition and tight crop, but wanted to see the lips not chopped on the left. The big flare really adds interest to the whole image. Maybe it''s my monitor, but it looks a bit over-saturated and over-sharpened here. (On a side note, I think I recognize your model, so I''m not voting... and I think you are going to win your BYOAKC match). Good luck!</td>', 'I like the composition and tight crop, but wanted to see the lips not chopped on the left. The big flare really adds interest to the whole image. Maybe it''s my monitor, but it looks a bit over-saturated and over-sharpened here. (On a side note, I think I recognize your model, so I''m not voting... and I think you are going to win your BYOAKC match). Good luck!', '2011-09-09 02:32:47.000000', NULL, 1),
(6534520, 970814, 96574, '<td valign="top">keep coming back to this one. the tones are superb and the flare adds to the overall feel of the image. my only critique is i wish there was a bit more light/dark contrast on the figure. bumping this up to a 9</td>', 'keep coming back to this one. the tones are superb and the flare adds to the overall feel of the image. my only critique is i wish there was a bit more light/dark contrast on the figure. bumping this up to a 9', '2011-09-09 03:29:38.000000', NULL, 1),
(6534546, 971076, 124700, '<td valign="top">My top pick. Great colours and the lens flare just adds to the beauty. 10</td>', 'My top pick. Great colours and the lens flare just adds to the beauty. 10', '2011-09-09 04:05:51.000000', NULL, 1),
(6534547, 970952, 124700, '<td valign="top">Absolutely love the burnt sienna colours here. The lens flare just increases the beauty of an already magnificent shot. 10</td>', 'Absolutely love the burnt sienna colours here. The lens flare just increases the beauty of an already magnificent shot. 10', '2011-09-09 04:06:00.000000', NULL, 1),
(6534548, 971348, 124700, '<td valign="top">The lens flare has added interest to the photo.  Well done.</td>', 'The lens flare has added interest to the photo.  Well done.', '2011-09-09 04:06:10.000000', NULL, 1),
(6534549, 971284, 124700, '<td valign="top">Beautiful soft tones.  The lens flare has added a lovely aura to the shot.</td>', 'Beautiful soft tones.  The lens flare has added a lovely aura to the shot.', '2011-09-09 04:06:14.000000', NULL, 1),
(6534550, 971363, 124700, '<td valign="top">Very pretty.</td>', 'Very pretty.', '2011-09-09 04:06:19.000000', NULL, 1),
(6534551, 971347, 124700, '<td valign="top">Great photo of not only the suns rays but the lens flare just adds to it.</td>', 'Great photo of not only the suns rays but the lens flare just adds to it.', '2011-09-09 04:06:28.000000', NULL, 1),
