(6534861, 971121, 113156, '<td valign="top">I have to say that this is one of my favorites, nothing to do with you being my teammate, i just love it.</td>', 'I have to say that this is one of my favorites, nothing to do with you being my teammate, i just love it.', '2011-09-09 14:04:37.000000', NULL, 1),
(6535018, 970944, 108580, '<td valign="top">Awesome flare patterns! Pretty darn unusual. I''ve not seen this phenomenon in a DSLR :) Love it.</td>', 'Awesome flare patterns! Pretty darn unusual. I''ve not seen this phenomenon in a DSLR :) Love it.', '2011-09-09 18:52:43.000000', NULL, 1),
(6535162, 971051, 133786, '<td valign="top">This is a really cool idea! Very simple... and executed superbly. Much love the cool tone, and think it works better than it would have been in black and white.</td>', 'This is a really cool idea! Very simple... and executed superbly. Much love the cool tone, and think it works better than it would have been in black and white.', '2011-09-09 22:21:28.000000', NULL, 1),
(6535173, 970952, 133786, '<td valign="top">This is beautiful. You can really get a sense of the warmth of the morning glow and you managed to keep texture and detail in the trees/cloud/fog. Love it! Is this done with HDR?</td>', 'This is beautiful. You can really get a sense of the warmth of the morning glow and you managed to keep texture and detail in the trees/cloud/fog. Love it! Is this done with HDR?', '2011-09-09 22:30:26.000000', NULL, 1),
(6535181, 970459, 83313, '<td valign="top">I want to follow, but I know I should run. The more I look at this, the more the feeling of dread grows. My only 10 so far for this challenge.</td>', 'I want to follow, but I know I should run. The more I look at this, the more the feeling of dread grows. My only 10 so far for this challenge.', '2011-09-09 22:38:46.000000', NULL, 1),
